/**
 * Slice 7 e2e fixture: a loopback mock of OpenAI's speech endpoint.
 *
 * The CI worker runs with OPENAI_API_BASE_URL pointing here, so the TTS
 * chunk job's synthesizeChunk() call (POST /v1/audio/speech) is answered
 * with a small generated MP3 — the same pattern as the s3mock for Hippius
 * and the article fixture server. No real OpenAI key is used in CI.
 *
 * Started by e2e/openai-server.ts (ensureOpenAiMock) — idempotent: if
 * something is already listening on the port it is left alone.
 *
 * Behavior:
 *   - POST /v1/audio/speech  → 200 audio/mpeg (the tiny MP3), and the request
 *     body is logged to stdout so the spec can assert the worker called the
 *     right model/voice and the chunk text.
 *   - Anything else → 404.
 */
import http from "node:http";

const PORT = Number(process.env.E2E_OPENAI_PORT ?? 3220);

// A 300 s silent MP3 (24 kHz mono, 8 kbps), base64. Generated once with:
//   ffmpeg -f lavfi -i anullsrc=r=24000:cl=mono -t 300 -codec:a libmp3lame -b:a 8k
// Long enough (5 min) that no chunk's <audio> ever ends during a test — headless
// Chromium may decode and play it regardless of the autoplay policy, and a
// chunk whose audio ENDS triggers the player's onended auto-advance, which
// races the highlight assertions. (Headless Chromium often blocks autoplay
// anyway; the length also guards the "autoplay worked" case.) Kept inline so
// CI never ships a binary.
const SILENT_MP3_B64 =
  "";

const SILENT_MP3 = Buffer.from(SILENT_MP3_B64, "base64");

let speechRequests = 0;

const server = http.createServer((req, res) => {
  if (req.method === "GET" && req.url === "/stats") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ speechRequests }));
    return;
  }
  if (req.method === "POST" && req.url === "/v1/audio/speech") {
    speechRequests += 1;
    let body = "";
    req.on("data", (c) => {
      body += c;
    });
    req.on("end", () => {
      // Log the request so the e2e can verify model/voice/input made it
      // through the worker unchanged. Keep it bounded.
      try {
        const parsed = JSON.parse(body || "{}");
        console.log(
          `[openai-mock] speech model=${parsed.model} voice=${parsed.voice} chars=${
            typeof parsed.input === "string" ? parsed.input.length : "?"
          }`,
        );
      } catch {
        console.log(`[openai-mock] speech (unparsed body, ${body.length} bytes)`);
      }
      res.writeHead(200, {
        "content-type": "audio/mpeg",
        "content-length": SILENT_MP3.length,
      });
      res.end(SILENT_MP3);
    });
    return;
  }
  res.writeHead(404, { "content-type": "text/plain" });
  res.end("not found");
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`[openai-mock] listening on http://127.0.0.1:${PORT}/v1/audio/speech`);
});
